// ── Build Brand-Months (3-Month Rolling fan-out, A06 'Build branches' pattern) ──
// Expands each brand into N items, one per month_offset, so the existing per-brand
// generation chain runs ONCE PER (brand, month) — producing 3 calendars from a
// SINGLE A01 run. rolling mode decides how many months:
//   'initial' (strategy-approval / onboarding / monthly seed) → [0,1,2] = full runway
//   'append'  (1st-of-month cron)                              → [2]     = new far month
//   'single'  (nightly weekly upkeep / explicit offset)        → [month_offset]
const cfg = $('Prepare Batch Config').first().json;
const rolling = cfg.rolling || 'single';
const offsets = rolling === 'initial' ? [0,1,2]
              : rolling === 'append'  ? [2]
              : [ (typeof cfg.month_offset==='number' ? cfg.month_offset : 0) ];
const out = [];
for (const item of $input.all()) {
  const b = item.json;
  if (!b || !b.brand_id) continue;
  for (const off of offsets) out.push({ json: { ...b, _month_offset: off } });
}
return out;

// 3-Month Rolling — 1st-of-month cron path. Sends rolling:'append' so A01's
// Build Brand-Months fan-out appends ONLY the new far month (+2); months 0 & 1
// already exist. batch_type MONTHLY = process all active brands.
return [{ json: { body: { rolling: 'append', batch_type: 'MONTHLY', source: 'rolling-cron' } } }];

// ── Skeleton Builder (Decoupled Producer) ─────────────────────────────────────
// Pure deterministic assembly. NO image generation, NO HTTP. One brand per run.
// Folds in the old Merge Posts mapping + Spine pre-gen compliance.
// Output: rows for ONE bulk insert into calendar_posts.
//   ALL posts → 'pending_visual' (every post generates an image; compliance
//   status = 'pending_visual' → everything else; the V01 Worker will claim it.
const crypto = require('crypto');
const ARABIC_RE = /[؀-ۿݐ-ݿﭐ-﷿ﹰ-﻿]/;

const brandData = $('Prepare Brand Data3').last().json;

// posts: prefer Match Chain output, then DeepSeek
let posts_raw = [];
try {
  const m = $('Call: Match Chain').last().json || {};
  posts_raw = (m.result && m.result.posts) || m.posts || [];
} catch(_) {}
if (!posts_raw.length) { try { posts_raw = $('Call: DeepSeek Generate').last().json?.result?.posts || []; } catch(_) {} }

// plan slots (chain_id + format)
let planSlots = [];
try { const ps = $('Call: Plan Slots3').last().json || {}; planSlots = (ps.result || ps).slots || []; } catch(_) {}

// CCO scores
let ccoResult = [];
try { ccoResult = $('Call: CCO Quality Check').last().json.result || []; } catch(_) {}

// CEO gate
let human_gate = false, confidence_mode = 'Standard';
try { human_gate = $('Call: CEO Confidence Gate').last().json.result?.decision?.human_gate_required || false; } catch(_) {}
// Per-post human-override holds (the 11 triggers, Doc §6.4) computed deterministically
// by /api/agents/ceo/confidence-gate. Map post_id -> [{trigger,reason,detail}].
let humanOverridesByPost = {};
try { humanOverridesByPost = $('Call: CEO Confidence Gate').last().json.result?.human_overrides?.per_post || {}; } catch(_) {}
// Per-post pillar scores (Doc §9.3) from confidence-gate: visual/caption/brand_fit/occasion.
// Stored in calendar_posts.flags.pillars so score-insight.tsx can show the 4-pillar breakdown.
let pillarsByPost = {};
try {
  const ps = $('Call: CEO Confidence Gate').last().json.result?.post_scores || $('Call: CEO Confidence Gate').last().json.post_scores || [];
  for (const p of ps) { if (p?.post_id && p?.pillars) pillarsByPost[p.post_id] = p.pillars; }
} catch(_) {}
try { confidence_mode = $('Call: CEO Route & Classify3').last().json.result?.decision?.confidence_mode || 'Standard'; } catch(_) {}

// calendar_id from HTTP: Upsert Calendar1 (this node's input)
const _calRaw = $input.first().json;
const calIn = Array.isArray(_calRaw) ? _calRaw[0] : _calRaw;
const calendarId = calIn?.calendar_id || calIn?.id || null;

const scheduleDates = brandData.schedule_dates || [];
const holdThreshold = confidence_mode === 'Cautious' ? 65 : 50;
const isMinimal = confidence_mode === 'Minimal';

// ── Spine compliance constants (pre-generation hard blocks) ──
const RELIGIOUS_PATTERNS = [
  /[؀-ۿ].*(?:قرآن|آية|حديث|الصلاة|الزكاة|الحج|سورة|دعاء)/u,
  /\b(quran|hadith|prophet\s+muhammad|pbuh|sallallahu|salah|zakat|islamic\s+prayer|dua\b|surah)\b/i,
];
const GESTURE_HARD_BLOCKS = [
  'left hand serv','left hand exchang','left hand offer','sole point','sole of foot',
  'beckoning palm','palm.up beckon','cross.gender contact','cross gender contact',
  'quran.*mishandl','mishandl.*quran',
];

function getOccasionVisualMotif(occasions){
  if(!occasions||occasions.length===0) return 'celebratory motion';
  const o=occasions[0];
  if(o==='ramadan') return 'warm spiritual motif with crescent and lanterns';
  if(o==='eid_al_fitr'||o==='eid_al_adha') return 'joyful celebratory motif with stars and lights';
  if(o==='national_day') return 'patriotic motif with green and gold, Saudi flag elements';
  if(o==='founding_day') return 'heritage motif with traditional architecture and maps';
  return 'celebratory motion';
}

if (!brandData?.brand_id) throw new Error('Skeleton Builder: missing brand_id');
if (!calendarId)          throw new Error('Skeleton Builder: no calendar_id');
if (posts_raw.length===0) throw new Error('Skeleton Builder: zero posts for ' + brandData.brand_id);

const out = posts_raw.map((caption, index) => {
  const slot = planSlots[index] || {};
  const sched = scheduleDates[index] || {};
  // Format source of truth (Doc §9.5, current design): ONE authority per post, never
  // a union (a union of DeepSeek's + plan-slots' video picks can exceed VIDEO_CAP and
  // blow the video cost budget). Priority: DeepSeek self-decided `caption.format`
  // (the current design — "DeepSeek replaces plan-slots"); if DeepSeek gave no format
  // for this post, use plan-slots `slot.format`; else 'image' (doc: normal = image-only).
  // The old is_video_slot tier heuristic is removed entirely.
  // FORMAT = SINGLE AUTHORITY: plan-slots (the deterministic doc §9.5 engine) decides
  // image vs video — NOT DeepSeek. The doc model is: every post defaults to IMAGE, and
  // plan-slots promotes a small CAPPED set to video based on tier + active occasion +
  // whether a video chain exists (pickVideoSlots). Letting DeepSeek's per-post
  // caption.format win (the old `_dsFmt ||` here) let a non-deterministic LLM promote
  // random posts to video, ignoring VIDEO_CAP/occasion → cost blowups + 'why is THIS a
  // video?' confusion. DeepSeek owns caption + content_type; format is plan-slots only.
  const _planFmt = (slot.format === 'image' || slot.format === 'video') ? slot.format : (slot.format_tier === 'video' ? 'video' : null);
  const format_tier = _planFmt || 'image';
  // CHAIN AUTHORITY: match-chain (content-aware, post-generation) is the source of
  // truth — it read this post's caption + visual_brief and picked the meaningful chain.
  // plan-slots' pre-generation score is only a fallback if match-chain returned nothing.
  const chain_id = caption.chain_id || slot.chain_id || null;

  const score_obj = Array.isArray(ccoResult) ? (ccoResult.find(s=>s.post_id===caption.post_id) || {}) : {};
  // FAIL-SAFE (was: default 75 = CLEAN). A missing/malformed CCO result must
  // NOT silently auto-publish. Score stays null and the post is force-routed
  // to human review (see needs_review below) so a CCO outage fails CLOSED.
  const cco_failed = typeof score_obj.score !== 'number';
  const cco_score = cco_failed ? null : score_obj.score;
  if (cco_failed) console.warn('[A01] CCO returned no score for post=' + caption.post_id + ' brand=' + brandData.brand_id + ' — holding for review');

  // visual_brief_en — ENGLISH ONLY (Hard Rule #3). Strip any Arabic leak.
  let visual_brief_en = (caption.visual_brief_en || caption.prompt_en || (brandData.brand_name_en + ' product Saudi Arabia')).trim();
  if (ARABIC_RE.test(visual_brief_en)) {
    visual_brief_en = (brandData.brand_name_en || 'product').replace(ARABIC_RE,'').trim() || 'product photography Saudi Arabia';
  }

  // ── Spine pre-gen compliance → hard_block decision ──
  const briefLower = visual_brief_en.toLowerCase();
  const captionText = caption.caption_ar || '';
  const combined = captionText + ' ' + briefLower;
  let hard_block = false, hold_reason = null, negpat = score_obj.negpat_flag || 'NONE';

  if ((brandData.religious_sensitivity||'') === 'High') {
    for (const p of RELIGIOUS_PATTERNS) { if (p.test(combined)) { hard_block=true; hold_reason='compliance_religious_content'; break; } }
  }
  if (!hard_block) {
    for (const kw of GESTURE_HARD_BLOCKS) { if (new RegExp(kw,'i').test(briefLower)) { hard_block=true; hold_reason='gesture_hard_block'; break; } }
  }
  if (!hard_block && negpat === 'HARD_BLOCK') { hard_block=true; hold_reason='negpat_hard_block'; }
  if (!hard_block && (brandData.sector||'').toLowerCase()==='government') { hard_block=true; hold_reason='government_sector'; }

  // ── Merge the 11 deterministic human-override triggers (Doc §6.4) ──
  // These come from the CEO confidence-gate. They NEVER block generation — the
  // image is always produced (Point 1); they only force requires_human_review so
  // the post is routed to /admin/qa with the exact reasons for the human admin.
  const overrideHolds = humanOverridesByPost[caption.post_id] || [];
  const overrideHeld = overrideHolds.length > 0;
  const overrideReason = overrideHeld ? overrideHolds[0].reason : null;
  const overrideDetails = overrideHolds.map(h => h.detail);
  // A post is held-for-review if EITHER a pre-gen hard_block OR any override fired.
  // cco_low_confidence is the existing trigger key for 'score too low / unknown'.
  const needs_review = hard_block || overrideHeld || cco_failed;
  const final_hold_reason = hold_reason || overrideReason || (cco_failed ? 'cco_scoring_unavailable' : null);

  const product_descriptor = brandData.brand_differentiator || brandData.brand_name_en || 'product';
  const palette = (brandData.primary_color_hex||'#000000') + ' and ' + (brandData.secondary_color_hex||'#ffffff');
  const occasion = (brandData.occasions && brandData.occasions[0] && brandData.occasions[0]!=='none') ? brandData.occasions[0] : '';

  return { json: {
    post_id: crypto.randomUUID(), calendar_id: calendarId, brand_id: brandData.brand_id,
    position: index+1, chain_id,
    caption_ar: caption.caption_ar || null, hashtags: caption.hashtags || [],
    content_type: slot.content_type || caption.content_type || 'emotional',
    posting_time: sched.posting_time || caption.posting_time || null,
    visual_brief_en, image_prompt_en: visual_brief_en, format: format_tier,
    cco_score, confidence_score: cco_score,
    negpat_flag: negpat, brave_route_flag: score_obj.brave_route_flag || false,
    dialect_flag: score_obj.dialect_flag || false,
    // Persist the FULL CCO evaluation (migration 0111). These columns now exist
    // on calendar_posts, so the structured 'why this score' survives to the DB
    // instead of being silently dropped by PostgREST.
    cultural_flag: score_obj.cultural_flag || false,
    cco_issues: Array.isArray(score_obj.issues) ? score_obj.issues : [],
    method_adherence_score: (typeof score_obj.method_adherence_score === 'number') ? score_obj.method_adherence_score : null,
    product_descriptor, brand_color_palette: palette,
    occasion_visual_motif: format_tier==='video' ? getOccasionVisualMotif(brandData.occasions) : null,
    occasion, brand_name_ar: brandData.brand_name_ar || null, dialect: brandData.arabic_dialect || null,
    font_color: caption.font_color || '#FFFFFF', font_size: caption.font_size || 48,
    sharp_text_gravity: caption.sharp_text_gravity || 'south',
    primary_color_hex: brandData.primary_color_hex || '', sector: brandData.sector || '',
    channel: brandData.primary_channel || 'Instagram',
    // ── DECOUPLE: standard posts wait for the Worker; only hard fails are blocked ──
    // POLICY (June 2026): generate an image for EVERY post so admin sees the real
    // visual before deciding. Compliance issues no longer auto-block generation —
    // carried as a flag (hold_reason + requires_human_review) so the post is
    // force-routed to admin review in QA AFTER its image is generated.
    status: 'pending_visual',
    hold_reason: final_hold_reason,
    route_decision: null,
    requires_human_review: needs_review || undefined,
    // Full trigger reasons for the /admin/qa UI (why this post was flagged).
    human_gate_triggers: overrideHolds.length ? overrideHolds : undefined,
    human_gate_detail: overrideDetails.length ? overrideDetails.join(' ') : (hard_block ? hold_reason : undefined),
    // Store 4-pillar scores in flags.pillars so score-insight.tsx shows real values.
    // pillarsByPost is populated from confidence-gate post_scores above.
    flags: pillarsByPost[caption.post_id] ? { pillars: pillarsByPost[caption.post_id] } : undefined,
    watermark: false, visual_failed: false,
  }};
});
return out;

const now = new Date();
const currMonth = now.getMonth();
const currYear  = now.getFullYear();
const dayOfWeek = now.getDay();
const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
let target_month = currMonth, target_year = currYear;
let target_month_key = target_year + '-' + String(target_month+1).padStart(2,'0');
let off_days = [0,6];
try { const raw = '0,6'; if(raw) off_days=raw.split(',').map(n=>parseInt(n.trim(),10)).filter(n=>!isNaN(n)); } catch(_){}
const DOW_TO_SHARD = {0:0,1:1,2:2,3:3,4:4};
let batch_type  = now.getDate()===1?'MONTHLY':'WEEKLY';
let batch_shard = batch_type==='WEEKLY'?(DOW_TO_SHARD[dayOfWeek]??0):null;
const daysInMonth = new Date(currYear,currMonth+1,0).getDate();
const is_last_sunday = dayOfWeek===0 && (now.getDate()+7)>daysInMonth;
let batch_id = batch_type==='MONTHLY'?'monthly-'+target_month_key:'shard-'+batch_shard+'-'+target_month_key;
let month_offset=0, target_brand_id=null, is_partial=false, partial_start_date=null, webhook_occasion_flags=null;
let rolling = null; // 'initial' (3 months) | 'append' (just +2) | 'single' (1)
let off_days_csv = '0,6';   // app forwards .env.local OFF_DAYS here (dynamic, not hardcoded)
let posts_per_week = null;    // brand cadence; default decided downstream (doc: 4-5/wk)
let bodyFound = false;        // SAFETY: true only when a real webhook/cron body arrived
try {
  // Body source: the webhook (onboarding/admin/manual triggers) OR the upstream
  // 'Set Rolling Offset' code node (the 1st-of-month cron path injects month_offset=2).
  // n8n throws if a referenced node wasn't in the execution path, so guard each.
  let body = {};
  try { body = $('Webhook: openclaw-batch-calendar').first().json.body || {}; } catch(_) {}
  if (!body || Object.keys(body).length === 0) {
    try { body = $('Set Rolling Offset').first().json.body || {}; } catch(_) {}
  }
  // SAFETY GUARD: was this triggered by a REAL source (webhook body or cron-offset
  // node)? If neither produced a body, it's a bare manual 'Execute workflow' click —
  // which would otherwise default to MONTHLY = ALL brands (a 6-hour, rate-limit-
  // blowing accident). We cap that case below. Stored on output as manual_unsafe.
  bodyFound = !!(body && Object.keys(body).length > 0);
  if(body.brand_id) target_brand_id=body.brand_id;
  if(body.batch_type) batch_type=body.batch_type;
  if(typeof body.batch_shard==='number') batch_shard=body.batch_shard;
  else if(batch_type==='WEEKLY') batch_shard=batch_shard??(DOW_TO_SHARD[dayOfWeek]??0);
  batch_id=batch_type==='MONTHLY'?'monthly-'+target_month_key:'shard-'+batch_shard+'-'+target_month_key;
  if(body.partial===true&&body.start_date){is_partial=true;partial_start_date=body.start_date;}
  if(target_brand_id&&!body.batch_type){batch_type='MONTHLY';batch_shard=null;batch_id='monthly-'+target_month_key;}
  if(typeof body.month_offset==='number'&&body.month_offset>=0&&body.month_offset<=2) month_offset=body.month_offset;
  if(typeof body.rolling==='string') rolling=body.rolling;
  if(typeof body.off_days==='string') off_days_csv = body.off_days;
  if(Array.isArray(body.off_days)) off_days = body.off_days;
  if(typeof body.posts_per_week==='number') posts_per_week = body.posts_per_week;
  if(target_brand_id&&!is_partial&&now.getDate()>1){is_partial=true;const _y=now.getFullYear();const _m=String(now.getMonth()+1).padStart(2,'0');const _d=String(now.getDate()).padStart(2,'0');partial_start_date=_y+'-'+_m+'-'+_d;}
  if(body.occasion_flags&&Array.isArray(body.occasion_flags)) webhook_occasion_flags=body.occasion_flags;
} catch(e){}
if(month_offset>0){
  const od=new Date(target_year,target_month+month_offset,1);
  target_month=od.getMonth(); target_year=od.getFullYear();
  target_month_key=target_year+'-'+String(target_month+1).padStart(2,'0');
  batch_id=batch_type==='MONTHLY'?'monthly-'+target_month_key+'-offset'+month_offset:'shard-'+batch_shard+'-'+target_month_key;
  is_partial=false; partial_start_date=null;
}
// Default rolling mode: explicit body.rolling wins; else MONTHLY batch = seed 3
// months (initial), WEEKLY/nightly = single current month.
if(!rolling) rolling = (batch_type==='MONTHLY') ? 'initial' : 'single';

// ── SAFETY CAP (prevents the 'Execute workflow' accident) ────────────────────
// A bare manual Execute click produces NO body (no webhook, no cron-offset) and no
// brand_id → it would fan out MONTHLY across ALL brands (≈63 × 3 months ≈ 6 hours,
// blowing the OpenAI/DeepSeek rate limits and producing nothing). Detect that exact
// case and CAP it to a tiny dev batch so an accidental click is harmless. Real
// triggers (single-brand webhook, cron) are unaffected.
const DEV_SAFE_BRAND_CAP = 2;            // accidental manual run touches ≤2 brands
// Distinguish a bare 'Execute workflow' click from a real cron/webhook trigger.
// n8n sets $execution.mode = 'manual' ONLY for editor Execute clicks; cron/webhook
// runs are 'trigger'/'webhook'. So a manual run with no body and no brand_id is the
// dangerous accident — a real nightly cron (also bodyless) is NOT manual, so it runs full.
let _execMode = 'trigger';
try { _execMode = $execution.mode; } catch(_) {}
const manual_unsafe = (_execMode === 'manual') && !bodyFound && !target_brand_id;
let max_brands_per_batch = batch_type==='MONTHLY' ? 500 : 60;
if (manual_unsafe) {
  max_brands_per_batch = DEV_SAFE_BRAND_CAP;
  // also force single-month so an accidental click can't fan to 3× either
  rolling = 'single';
}
return [{ json:{target_month,target_year,target_month_name:monthNames[target_month],target_month_key,batch_type,batch_shard,is_last_sunday,batch_id,generated_at:now.toISOString(),target_brand_id,off_days,is_partial,partial_start_date,expected_posts_per_brand:20,month_offset,max_brands_per_batch,manual_unsafe,webhook_occasion_flags,rolling,off_days,off_days_csv,posts_per_week} }];

const batchCfg = $("Prepare Batch Config").first().json;
const targetBrandId = batchCfg.target_brand_id||null;
// SAFETY CAP: enforce max_brands_per_batch. On a bare manual 'Execute' click,
// Prepare Batch Config sets this to a tiny number (DEV_SAFE_BRAND_CAP) + manual_unsafe,
// so an accidental click processes only a couple of brands instead of all ~63.
const maxBrands = Number(batchCfg.max_brands_per_batch) || 500;
const seen = new Set(); const result = [];
for (const item of $input.all()) {
  const b = item.json;
  if(!b.brand_id) continue;
  if(b.tier==='free'&&(b.total_calendars_generated||0)>=3) continue; // free = 3 onboarding months, then stop
  if(targetBrandId&&b.brand_id!==targetBrandId) continue;
  if(!seen.has(b.brand_id)){seen.add(b.brand_id);result.push({json:b});}
  if(result.length >= maxBrands) break; // hard cap (also the dev-safe guard)
}
if (batchCfg.manual_unsafe) {
  console.warn('[A01] MANUAL UNSAFE run detected (bare Execute click, no brand_id) — capped to ' + result.length + ' brand(s). For a real run, trigger via webhook with brand_id, or via cron.');
}
return result;

// ── KICK V01 WORKER (fires ONCE, when A01 has finished ALL months) ───────────
// Runs off the Loop Guard (loop 'done' branch), so it triggers exactly once after
// the whole 3-month run is written to the DB — NOT per brand. One ping drains the
// entire calendar because the Worker now claim-all-then-batches internally.
// Fire-and-forget: a failure here must NEVER fail A01 (the Worker's 1-min cron is a
// safety net that picks the posts up anyway). TESTING uses /webhook-test/.
const WORKER_WEBHOOK = 'https://ogzstudios.app.n8n.cloud/webhook-test/openclaw-run-worker';
try {
  await this.helpers.httpRequest({
    method: 'POST', url: WORKER_WEBHOOK,
    headers: { 'content-type': 'application/json' },
    body: { source: 'N8N-A01-complete', triggered_at: new Date().toISOString(),
            expected: ($json && $json.expected) || null, completed: ($json && $json.completed) || null },
    json: true, timeout: 8000,
  });
} catch (e) { /* Worker cron will still pick the posts up — non-fatal */ }
return $input.all();

// $input here is the OUTPUT of 'Insert Calendar Lease3' (HTTP node) — the Supabase
// CALENDARS row {calendar_id, brand_id, month, status}. It has NO brand identity
// (brand_name_ar/en, sector, dialect, city, …), so reading those off it yields
// undefined → COO/CEO/DeepSeek/CCO all ran on 'Brand: undefined' + generic F&B
// defaults. ROOT-CAUSE FIX (same pattern as the _month_offset recovery below):
// recover the REAL per-iteration brand object from the splitInBatches loop item
// (batchSize=1 → .last() IS this iteration's brand), then keep calendar_id from
// the lease row so the calendar linkage stays correct.
const leaseRow = $input.first().json;
let brandSrc = {};
if (leaseRow && leaseRow.brand_name_ar) {
  brandSrc = leaseRow; // already has identity (shouldn't normally, but harmless)
} else {
  for (const nm of ['Loop Over Items','Build Brand-Months2','Build Brand-Months']) {
    try { const v = $(nm).last().json; if (v && v.brand_name_ar) { brandSrc = v; break; } } catch(_) {}
  }
}
// Merge: real brand identity wins; carry calendar_id/brand_id from the lease row.
const brand = { ...brandSrc, ...leaseRow, brand_name_ar: brandSrc.brand_name_ar ?? leaseRow.brand_name_ar, brand_name_en: brandSrc.brand_name_en ?? leaseRow.brand_name_en };
// Keep identity fields the lease row doesn't have (spread of leaseRow above would
// only override keys it actually contains, so brandSrc's sector/dialect/etc. survive).
const batchConfig = $('Prepare Batch Config').first().json;
// Off-days are DYNAMIC: app reads .env.local OFF_DAYS and forwards it in the
// webhook body → Prepare Batch Config → here. Default Sun(0)+Sat(6) if absent.
const offDaysRaw = (Array.isArray(batchConfig.off_days) && batchConfig.off_days.length)
  ? batchConfig.off_days
  : String(batchConfig.off_days_csv || '0,6').split(',').map(s=>parseInt(s.trim(),10)).filter(n=>!isNaN(n));
// 3-Month Rolling: each brand item carries its OWN _month_offset (0/1/2) from
// Build Brand-Months, so this run builds THAT month's calendar. Shift the base
// target month by the per-item offset.
// ── ROOT-CAUSE FIX (3-month rolling): recover _month_offset for THIS iteration. ──
// $input.first() here is the OUTPUT of 'Insert Calendar Lease3' (an HTTP node), which
// REPLACES the item with the Supabase calendar row {calendar_id,brand_id,month,...}
// — that row has NO _month_offset, so reading brand._month_offset was ALWAYS undefined
// → fell back to 0 → every month built the offset-0 (current, partial 15-post) schedule.
// THAT is why July/Aug got 15 June-shaped posts. The brand item that DOES carry
// _month_offset is the current iteration's item on the splitInBatches loop. Read it
// from $('Loop Over Items').last() (batchSize=1 → that IS this iteration's item).
let _off = (typeof brand._month_offset === 'number') ? brand._month_offset : null;
if (_off === null) {
  // current loop item (has _month_offset) — try the loop node, then Build Brand-Months.
  for (const nm of ['Loop Over Items','Build Brand-Months2','Build Brand-Months']) {
    try { const v = $(nm).last().json._month_offset; if (typeof v === 'number') { _off = v; break; } } catch(_) {}
  }
}
if (_off === null) _off = (typeof batchConfig.month_offset === 'number') ? batchConfig.month_offset : 0;
