// admin is told exactly which month/brand failed and why.
let brand_id=null, month_key=null, reason='month_skipped';
for (const nm of ['Prepare Brand Data3','Prepare Brand Data']) {
  try { const j=$(nm).last().json; brand_id=j.brand_id||brand_id; month_key=j.month_key||month_key; } catch(_){}
}
// infer reason from which upstream node fed us
try { if ($('IF: Brand Blocked?3').last().json) reason='brand_blocked'; } catch(_){}
try { const q=$('Supabase: Log to QA Queue').last().json; if(q) reason='dialect_not_confirmed'; } catch(_){}
return [{ json: {
  error: { node: { name: 'Strict Month Gate' } },
  node_name: 'Strict Month Gate',
  error_message: 'A01 STRICT GATE: month ' + (month_key||'?') + ' for brand ' + (brand_id||'?')
    + ' was SKIPPED (' + reason + ') — loop STOPPED, later months NOT generated. Fix and re-run.',
  brand_id, _skip:{ brand_id, month_key, reason },
}}];

// Cost ceiling pre-flight — reads brand_cost_config.cost_blocked (O(1) single row).
// Maintained in real-time by fn_cost_ceiling_enforcer DB trigger on usage_logs.
// Placed after Calendar Lease insert, before Prepare Brand Data.
const SUPABASE_URL         = 'https://redzmrlzhxkkpgcokgvl.supabase.co';
const SUPABASE_SERVICE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;

const brand_id = $json.brand_id
  ?? $('Prepare Batch Config').first().json.target_brand_id
  ?? null;

if (!brand_id) {
  return { ...$json, cost_allowed: true, cost_status: 'unknown', cost_context: {} };
}

let costRow = null;
try {
  const res = await $helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/brand_cost_config?brand_id=eq.${brand_id}&select=cost_blocked,current_month_cost_usd,monthly_ceiling_usd,halt_at_pct,alert_at_pct`,
    headers: {
      apikey: SUPABASE_SERVICE_KEY,
      Authorization: `Bearer ${SUPABASE_SERVICE_KEY}`,
    },
    json: true,
  });
  costRow = Array.isArray(res) ? res[0] : null;
} catch (e) {
  console.error('[cost-check] fetch failed:', e.message);
  // Non-fatal: allow generation so a DB hiccup never blocks the batch.
  return { ...$json, cost_allowed: true, cost_status: 'fetch_error', cost_context: {} };
}

if (!costRow) {
  return { ...$json, cost_allowed: true, cost_status: 'no_config', cost_context: {} };
}

const spend_pct = costRow.monthly_ceiling_usd > 0
  ? Math.round((costRow.current_month_cost_usd / costRow.monthly_ceiling_usd) * 100)
  : 0;

const cost_status = costRow.cost_blocked
  ? 'breached'
  : spend_pct >= costRow.alert_at_pct
    ? 'approaching'
    : 'normal';

const cost_context = {
  brand_id,
  cost_blocked:            costRow.cost_blocked,
  current_month_spend_usd: costRow.current_month_cost_usd,
  monthly_ceiling_usd:     costRow.monthly_ceiling_usd,
  spend_pct,
  cost_status,
};

return { ...$json, cost_allowed: !costRow.cost_blocked, cost_status, cost_context };
